root='/tmp/skillplane-pr-quality-20260912'; env=dict(os.environ,GH_CONFIG_DIR=os.path.expanduser('~/.config/gh-other'))
query='''query($n:Int!,$after:String){repository(owner:"21nCo",name:"skillplane"){pullRequest(number:$n){reviewThreads(first:100,after:$after){pageInfo{hasNextPage endCursor} nodes{id isResolved isOutdated path line comments(first:100){pageInfo{hasNextPage endCursor} nodes{id author{login} body url createdAt originalCommit{oid}}}}}}}}'''
def run(n):
 pages=[];after=None
 while True:
  args=['gh','api','graphql','-f','query='+query,'-F',f'n={n}']
  if after:args+=['-f','after='+after]
  p=subprocess.run(args,env=env,capture_output=True,text=True);d=json.loads(p.stdout);pages.append(d)
  conn=d['data']['repository']['pullRequest']['reviewThreads']
  if not conn['pageInfo']['hasNextPage']:break
  after=conn['pageInfo']['endCursor']
 open(f'{root}/pr-{n}/threads.json','w').write(json.dumps(pages,indent=2))
 for name,url in [('reviews',f'repos/21nCo/skillplane/pulls/{n}/reviews'),('comments',f'repos/21nCo/skillplane/issues/{n}/comments')]:
  p=subprocess.run(['gh','api','--paginate','--slurp',url],env=env,capture_output=True,text=True);open(f'{root}/pr-{n}/{name}.json','w').write(p.stdout)
 for page in pages:
  for t in page['data']['repository']['pullRequest']['reviewThreads']['nodes']:
   print(n,t['id'],t['isResolved'],t['isOutdated'],t['path'],t['line'],t['comments']['pageInfo'])
   for c in t['comments']['nodes']:print(c['author']['login'],c['url'],c['body'][:1600])
with concurrent.futures.ThreadPoolExecutor() as ex:list(ex.map(run,[15,18,19]))
PY`,max_output_tokens:9000}));

