export function createAuthFnHttpClient(options = {}) {
    const fetchImpl = options.fetch ?? fetch;
    const baseUrl = (options.baseUrl ?? '/auth').replace(/\/$/, '');
    const credentials = options.credentials ?? 'include';
    const cookieAccessor = options.cookieAccessor ?? defaultCookieAccessor;
    const cookiePrefix = options.cookiePrefix?.trim();
    const resolveBearerToken = async () => {
        if (!options.bearerToken) {
            return undefined;
        }
        const token = typeof options.bearerToken === 'function'
            ? await options.bearerToken()
            : options.bearerToken;
        return token?.trim() || undefined;
    };
    const buildTransportError = (error) => ({
        ok: false,
        error: {
            code: 'AUTHFN_NETWORK_ERROR',
            message: error instanceof Error
                ? error.message
                : 'AuthFn request failed before a response was received',
            retryable: true,
            details: error instanceof Error
                ? {
                    name: error.name,
                    stack: error.stack
                }
                : {
                    cause: error
                }
        },
        requestId: 'authfn-transport-error'
    });
    return {
        requestJson: async (request) => {
            const headers = new Headers();
            const url = `${baseUrl}${request.path}`;
            const startedAt = now();
            if (request.body !== undefined) {
                headers.set('content-type', 'application/json');
            }
            let response;
            try {
                const bearerToken = await resolveBearerToken();
                if (bearerToken) {
                    headers.set('authorization', `Bearer ${bearerToken}`);
                }
                if (request.csrf) {
                    const cookieHeader = cookieAccessor();
                    const csrfToken = readCookieValue(cookieHeader, `${cookiePrefix || readCookiePrefix(cookieHeader)}.csrf`);
                    if (csrfToken) {
                        headers.set('x-authfn-csrf', csrfToken);
                    }
                }
                response = await fetchImpl(url, {
                    method: request.method,
                    headers,
                    credentials,
                    body: request.body !== undefined ? JSON.stringify(request.body) : undefined
                });
            }
            catch (error) {
                options.onRequestMetric?.({
                    method: request.method,
                    path: request.path,
                    url,
                    ok: false,
                    durationMs: now() - startedAt,
                    error: error instanceof Error
                        ? {
                            name: error.name,
                            message: error.message
                        }
                        : {
                            message: String(error)
                        }
                });
                return buildTransportError(error);
            }
            options.onRequestMetric?.({
                method: request.method,
                path: request.path,
                url,
                status: response.status,
                ok: response.ok,
                durationMs: now() - startedAt,
                requestId: response.headers.get('x-request-id') ?? undefined,
