  const email = recipient();
  const code = process.env.SKILLPLANE_PRODUCTION_OTP_CODE?.trim();
  if (code !== undefined && !/^\d{6}$/u.test(code)) {
    throw new Error("SKILLPLANE_PRODUCTION_OTP_CODE must contain exactly six digits");
