for (const state of ['archived','all']) for (const search of [false,true]) {
 it('preserves state='+state+' with includeArchived=false; search='+search,async()=>{
  const listPage=vi.fn(async(input)=>({skills:[],nextCursor:null}));
  const app=new Hono();
  app.use('*',async(c,next)=>{c.set('services',{skillService:{listPage},skillSearchService:{search:listPage}});c.set('requestId','probe');await next();});
  registerSkillRoutes(app);
  const response=await app.request('/api/v1/workspaces/w/skills?includeArchived=false&state='+state+(search?'&q=hello':''));
  expect(response.status).toBe(200);
  expect(listPage.mock.calls[0][0].archive).toBe(state);
 });
}

