async function created(){const f=fixture();await f.provider.create({slug:'review',name:'Review',description:'Review changes',tags:[],visibility:'private',instructions:'Read carefully.',assets:[],idempotencyKey:'qa-create'});const [record]=await f.runtime.sync(f.project);return {...f,record};}
