import { beforeAll, afterAll, describe, it, expect } from "vitest";
import { Pool } from "pg";
import {
  canonicalizeBundleFiles,
  R2BundleRepository,
  type R2BucketLike,
  type SkillDependency,
} from "@skillplane/storage";
import { SkillService } from "../../src/skills.js";
