  IF OLD.status <> 'running' OR
    to_jsonb(OLD) - ARRAY['status','completed_at','evidence_manifest_digest'] IS DISTINCT FROM
    to_jsonb(NEW) - ARRAY['status','completed_at','evidence_manifest_digest'] THEN
