import { readdirSync, readFileSync, existsSync } from "node:fs";
import { resolve } from "node:path";
const alias = [];
for (const dir of readdirSync("packages")) {
  const root = resolve("packages", dir);
  const manifest = resolve(root, "package.json");
  if (!existsSync(manifest)) continue;
  const pkg = JSON.parse(readFileSync(manifest, "utf8"));
  const index = resolve(root, "src/index.ts");
  if (existsSync(index)) alias.push({ find: new RegExp("^" + pkg.name + "$"), replacement: index });
  for (const [key, value] of Object.entries(pkg.exports ?? {})) {
    if (!key.startsWith("./") || !value || typeof value !== "object") continue;
    const source = value.development;
    if (typeof source === "string") alias.push({ find: new RegExp("^" + pkg.name + key.slice(1) + "$"), replacement: resolve(root, source) });
  }
}
export default { resolve: { alias }, test: { include: ["review-probes.test.ts"], testTimeout: 15000 } };

